// LeaxPanel bootstrap - shared by every installer.
// Handles: .env generation, dependency install, migrations, seeds, RBAC, report.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execFileSync } = require('child_process');

const ROOT = path.join(__dirname, '..');
const ENV_PATH = path.join(ROOT, '.env');

function log(step, total, message) {
  console.log(`[${step}/${total}] ${message}`);
}

function randomHex(bytes = 32) {
  return crypto.randomBytes(bytes).toString('hex');
}

function randomPassword(length = 20) {
  // The alphabet avoids '#', '$', '"' and whitespace so the value survives
  // .env parsing, dotenv and shell expansion unchanged.
  const lower = 'abcdefghijkmnopqrstuvwxyz';
  const upper = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
  const digits = '23456789';
  const symbols = '!@%^*_-';
  const alphabet = lower + upper + digits + symbols;

  const bytes = crypto.randomBytes(length);
  let out = '';
  for (let i = 0; i < length; i++) out += alphabet[bytes[i] % alphabet.length];

  // Guarantee at least one of each class.
  out = lower[bytes[0] % lower.length] +
        upper[bytes[1] % upper.length] +
        digits[bytes[2] % digits.length] +
        symbols[bytes[3] % symbols.length] +
        out.slice(4);
  return out;
}

function readEnvFile() {
  if (!fs.existsSync(ENV_PATH)) return {};
  const out = {};
  for (const line of fs.readFileSync(ENV_PATH, 'utf8').split('\n')) {
    const match = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)$/);
    if (!match) continue;
    let value = match[2].trim();
    // Strip surrounding quotes written by quoteEnvValue().
    if (value.length >= 2 && ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'")))) {
      value = value.slice(1, -1).replace(/\\"/g, '"');
    }
    out[match[1]] = value;
  }
  return out;
}

const ENV_TEMPLATE = [
  ['NODE_ENV', 'production'],
  ['PORT', '3000'],
  ['HOST', '0.0.0.0'],
  ['SESSION_SECRET', ''],
  ['SESSION_MAX_AGE', '86400000'],
  ['JWT_SECRET', ''],
  ['JWT_EXPIRES_IN', '7d'],
  ['ENCRYPTION_KEY', ''],
  ['ADMIN_EMAIL', ''],
  ['ADMIN_PASSWORD', ''],
  ['ADMIN_NAME', 'Owner'],
  ['ADMIN_ROLE', 'owner'],
  ['DB_PATH', './data/leaxos.db'],
  ['PANEL_NAME', 'LeaxPanel'],
  ['PANEL_TAGLINE', 'Host Anything. Manage Everything. Deploy Anywhere.'],
  ['REGISTRATION_ENABLED', 'false'],
  ['BILLING_ENABLED', 'false'],
  ['BILLING_PROVIDER', 'manual'],
  ['MAINTENANCE_MODE', 'false'],
  ['BACKUP_ENABLED', 'true'],
  ['BACKUP_CRON', '0 3 * * *'],
  ['BACKUP_RETENTION_DAYS', '30'],
  ['MONITORING_INTERVAL', '30000'],
  ['RATE_LIMIT_WINDOW_MS', '900000'],
  ['RATE_LIMIT_MAX', '300'],
  ['DISCORD_WEBHOOK_URL', ''],
  ['OPENAI_API_KEY', ''],
  ['ANTHROPIC_API_KEY', ''],
  ['GOOGLE_API_KEY', ''],
  ['DEEPSEEK_API_KEY', ''],
  ['GROK_API_KEY', ''],
  ['OPENROUTER_API_KEY', ''],
  ['SMTP_HOST', 'localhost'],
  ['SMTP_PORT', '25'],
  ['SMTP_USER', ''],
  ['SMTP_PASSWORD', ''],
  ['SMTP_FROM', 'noreply@leaxos.local'],
  ['STRIPE_SECRET_KEY', ''],
  ['STRIPE_PUBLISHABLE_KEY', ''],
  ['STRIPE_WEBHOOK_SECRET', ''],
  ['PAYPAL_CLIENT_ID', ''],
  ['PAYPAL_CLIENT_SECRET', ''],
  ['PAYPAL_MODE', 'sandbox'],
  ['CLOUDFLARE_API_TOKEN', ''],
  ['CLOUDFLARE_ACCOUNT_ID', ''],
  ['CLOUDFLARE_ZONE_ID', '']
];

function writeEnv(overrides = {}) {
  const current = readEnvFile();
  const lines = [
    '# LeaxPanel(os) Environment Configuration',
    '# Generated by the installer - DO NOT COMMIT TO VERSION CONTROL',
    ''
  ];

  const credentials = {};

  for (const [key, fallback] of ENV_TEMPLATE) {
    let value = overrides[key] !== undefined && overrides[key] !== ''
      ? overrides[key]
      : (current[key] !== undefined && current[key] !== '' ? current[key] : fallback);

    if (value === '' && key === 'SESSION_SECRET') value = randomHex(32);
    if (value === '' && key === 'JWT_SECRET') value = randomHex(32);
    if (value === '' && key === 'ENCRYPTION_KEY') value = randomHex(32);
    if (value === '' && key === 'ADMIN_EMAIL') value = 'owner@leaxos.local';
    if (value === '' && key === 'ADMIN_PASSWORD') value = randomPassword(16);

    if (['SESSION_SECRET', 'JWT_SECRET', 'ENCRYPTION_KEY', 'ADMIN_EMAIL', 'ADMIN_PASSWORD'].includes(key)) {
      credentials[key] = value;
    }

    lines.push(`${key}=${quoteEnvValue(value)}`);
  }

  fs.writeFileSync(ENV_PATH, lines.join('\n') + '\n', 'utf8');
  return credentials;
}

/**
 * Quotes a value so dotenv (and shell tooling) reads it back verbatim.
 * Values containing '#', spaces or quotes must be wrapped in double quotes.
 */
function quoteEnvValue(value) {
  const str = String(value);
  if (str === '') return '';
  if (/^[A-Za-z0-9_.\/:@%^*+-]+$/.test(str)) return str;
  return `"${str.replace(/"/g, '\\"')}"`;
}

function ensureDirectories() {
  for (const dir of ['data', 'data/uploads', 'data/files', 'logs', 'backups']) {
    const full = path.join(ROOT, dir);
    if (!fs.existsSync(full)) fs.mkdirSync(full, { recursive: true });
  }
}

function runStep(label, file) {
  try {
    execFileSync(process.execPath, [path.join(ROOT, file)], {
      cwd: ROOT,
      stdio: 'inherit',
      // Pass the freshly generated .env values to the child process so the
      // seeds can create the administrator with the generated password.
      env: { ...process.env, ...readEnvFile() }
    });
    return true;
  } catch (err) {
    console.error(`    WARNING: ${label} failed: ${err.message}`);
    return false;
  }
}

function runNpm(args) {
  const isWindows = process.platform === 'win32';
  // On Windows npm is a .cmd shim, which cannot be spawned directly.
  const command = isWindows ? 'npm.cmd' : 'npm';
  const options = {
    cwd: ROOT,
    stdio: 'inherit',
    shell: isWindows
  };
  try {
    execFileSync(command, args, options);
    return true;
  } catch (err) {
    // Fall back to the shell when the direct spawn is rejected (EINVAL).
    if (err.code === 'EINVAL' || err.code === 'ENOENT') {
      try {
        execFileSync(`npm ${args.join(' ')}`, { cwd: ROOT, stdio: 'inherit', shell: true });
        return true;
      } catch (fallbackErr) {
        console.error(`    ERROR: npm ${args.join(' ')} failed: ${fallbackErr.message}`);
        return false;
      }
    }
    console.error(`    ERROR: npm ${args.join(' ')} failed: ${err.message}`);
    return false;
  }
}

function installDependencies() {
  console.log('    Installing npm dependencies (this can take a few minutes)...');
  return runNpm(['install', '--no-audit', '--no-fund']);
}

function main() {
  const total = 6;

  log(1, total, 'Preparing directories...');
  ensureDirectories();
  console.log('    data/, logs/ and backups/ are ready.');

  log(2, total, 'Generating configuration and credentials...');
  const credentials = writeEnv({
    ADMIN_EMAIL: process.env.ADMIN_EMAIL,
    ADMIN_PASSWORD: process.env.ADMIN_PASSWORD,
    ADMIN_NAME: process.env.ADMIN_NAME,
    PORT: process.env.PORT
  });
  console.log('    .env written with generated secrets.');

  log(3, total, 'Installing npm dependencies...');
  if (!installDependencies()) {
    console.error('    Cannot continue without dependencies.');
    process.exit(1);
  }

  log(4, total, 'Applying database migrations...');
  runStep('Migrations', path.join('migrations', 'run.js'));

  log(5, total, 'Seeding default roles and administrator...');
  runStep('Seeds', path.join('seeds', 'run.js'));

  log(6, total, 'Finalising permissions and preparing storage...');
  let adminVerified = false;
  try {
    const db = require(path.join(ROOT, 'config', 'db.js'));
    const rbac = require(path.join(ROOT, 'middleware', 'rbac.js'));
    rbac.initializeRoles();
    const users = db.get('SELECT COUNT(*) AS count FROM users');
    console.log(`    Roles and permissions synchronised (${users ? users.count : 0} user(s) registered).`);

    const bcrypt = require('bcryptjs');
    const admin = db.get('SELECT password_hash FROM users WHERE email = ?', [credentials.ADMIN_EMAIL]);
    if (admin && bcrypt.compareSync(credentials.ADMIN_PASSWORD, admin.password_hash)) {
      adminVerified = true;
      console.log('    Administrator credentials verified against the database.');
    } else if (admin) {
      console.error('    WARNING: the administrator password does not match the database hash.');
      console.error('    Run "npm run seed" again to apply the .env credentials.');
    }
  } catch (err) {
    console.error(`    WARNING: could not synchronise roles: ${err.message}`);
  }
  ensureDirectories();

  const banner = [
    '',
    '============================================================================',
    '  LeaxPanel(os) - Installation complete',
    '============================================================================',
    '',
    `  Panel URL:      http://localhost:${credentials.PORT || process.env.PORT || 3000}`,
    '',
    '  ADMINISTRATOR CREDENTIALS (save these now):',
    `    Email:         ${credentials.ADMIN_EMAIL}`,
    `    Password:      ${credentials.ADMIN_PASSWORD}`,
    '',
    '  Generated secrets (also stored in .env):',
    `    SESSION_SECRET: ${credentials.SESSION_SECRET}`,
    `    JWT_SECRET:     ${credentials.JWT_SECRET}`,
    `    ENCRYPTION_KEY: ${credentials.ENCRYPTION_KEY}`,
    '',
    '  NEXT STEPS:',
    '    1. Start the panel:   npm start   (or run.bat / ./run.sh)',
    '    2. Open:              http://localhost:3000',
    '    3. Health check:      http://localhost:3000/doctor',
    '    4. Setup wizard:      http://localhost:3000/setup',
    '',
    '  Documentation: https://github.com/netblood/LeaxPanel-OS-',
    '  Issues:         https://github.com/netblood/LeaxPanel-OS-/issues',
    '============================================================================',
    ''
  ].join('\n');

  console.log(banner);
  fs.writeFileSync(path.join(ROOT, 'INSTALL_CREDENTIALS.txt'), banner, 'utf8');
  console.log('  Credentials also written to INSTALL_CREDENTIALS.txt');
}

if (require.main === module) {
  main();
}

module.exports = { writeEnv, randomPassword, randomHex, ensureDirectories, readEnvFile };
